import numpy as np
from PIL import Image
for run in ('near_low','correct1','correct2'):
 for cam in ('front','right','topview'):
  a=np.asarray(Image.open(f'/app/runs/{run}/last/{cam}.jpg')).astype(int)
  g=(a[:,:,1]>150)&(a[:,:,1]>a[:,:,0]*1.5)&(a[:,:,1]>a[:,:,2]*1.5)
  ys,xs=np.where(g)
  if len(xs):print(run,cam,'green',len(xs),[round(float(np.median(xs)),1),round(float(np.median(ys)),1)],'bounds',(xs.min(),xs.max(),ys.min(),ys.max()))
